<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
/** Provides performance review behavior within the WorkIntel application. */ class PerformanceReview extends Model{protected $fillable=['uuid','workspace_id','cycle_id','member_id','manager_member_id','status','self_rating','manager_rating','overall_rating','self_summary','manager_summary','self_submitted_at','manager_submitted_at','completed_at'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['self_rating'=>'decimal:2','manager_rating'=>'decimal:2','overall_rating'=>'decimal:2','self_submitted_at'=>'datetime','manager_submitted_at'=>'datetime','completed_at'=>'datetime'];}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}/** Handles the manager operation for the current WorkIntel workflow. */ public function manager():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'manager_member_id');}/** Handles the cycle operation for the current WorkIntel workflow. */ public function cycle():BelongsTo{return $this->belongsTo(PerformanceReviewCycle::class,'cycle_id');}/** Handles the answers operation for the current WorkIntel workflow. */ public function answers():HasMany{return $this->hasMany(PerformanceReviewAnswer::class);}}
